    "sfLockSec1Step6": "মাস্টার কি সুরক্ষিত স্থানে সংরক্ষণ করুন। আপনি পিন ভুলে গেলে এটির প্রয়োজন হবে।",
    "sfLockSec1Step7": "লক করার পরে, চ্যাট লক করা চ্যাট ফোল্ডারে চলে যাবে।",
