    "sfLockAttemptsBullet1": "ব্যবহারকারীরা ২ বার পিন চেষ্টা করতে পারেন।",
    "sfLockAttemptsBullet2": "২ বার ভুল পিন দেওয়ার পরে, ৩০ সেকেন্ডের নিরাপত্তা লকআউট টাইমার প্রদর্শিত হবে।",
    "sfLockAttemptsBullet3": "লকআউটের সময়, পিন প্রবেশ সাময়িকভাবে নিষ্ক্রিয় করা হবে।",
    "sfLockAttemptsBullet4": "টাইমার শেষ হওয়ার পরে, আপনি পিনটি আবার চেষ্টা করতে পারেন বা শেষবারের জন্য মাস্টার কি ব্যবহার করতে পারেন।",
    "sfLockSec3Title": "স্বয়ংক্রিয় লক বৈশিষ্ট্য",
    "sfLockSec3Desc1": "আপনি আনলক করার পরে লক করা চ্যাট কতক্ষণ খোলা রাখতে হবে তা স্বয়ংক্রিয় লক নিয়ন্ত্রণ করে।",
    "sfLockSec3Desc2": "উপলব্ধ বিকল্পগুলি: অবিলম্বে · ১ মিনিট · ৫ মিনিট · ১৫ মিনিট · কখনই নয়",
    "sfLockSec3Desc3": "নির্বাচিত সময় শেষ হওয়ার পরে, চ্যাট স্বয়ংক্রিয়ভাবে আবার লক হবে। আবার খুলতে, আপনাকে পিনটি আবার প্রবেশ করতে হবে।",
    "sfLockSec3Path": "সেটিংস → লক করা চ্যাট → চ্যাট লক সেটিংস → স্বয়ংক্রিয় লক টাইমার",
    "sfLockSec4Title": "রুমের ভিতরে চ্যাট লক",
    "sfLockSec4Desc1": "আপনি রুমের ভেতর থেকে বা কথোপকথন উইন্ডো থেকে ব্যক্তিগত চ্যাট লক করলে, এটি সম্পূর্ণ অদৃশ্য হবে না।",
    "sfLockSec4Desc2": "ব্যক্তিগত চ্যাট রুম বা চ্যাট তালিকায় প্রদর্শিত হবে, তবে ডানদিকে একটি লক সূচক দেখাবে।",
    "sfLockSec4Desc3": "সেই লক করা ব্যক্তিগত চ্যাট খুলতে, আপনাকে পিন প্রবেশ করতে হবে।",
