    "sfBlockUserStep1": "അവരുടെ പ്രൊഫൈലിലേക്ക് പോകുക",
    "sfBlockUserStep2": "⋮ മെനു ക്ലിക്ക് ചെയ്യുക",
    "sfBlockUserStep3": "「യൂസറെ ബ്ലോക്ക് ചെയ്യുക」 തിരഞ്ഞെടുക്കുക",
    "sfBlockUserLink": "നിങ്ങളുടെ ബ്ലോക്ക് ചെയ്ത ലിസ്റ്റിലേക്ക് പോകുക →",
    "sfLockChatsTitle": "നിങ്ങളുടെ ചാറ്റുകൾ ലോക്ക് ചെയ്യുക",
    "sfLockChatsDesc": "അധിക സ്വകാര്യതയ്ക്കായി നിങ്ങളുടെ സ്വകാര്യ ചാറ്റുകളിലേക്ക് 6-അക്ക പിൻ ചേർക്കുക. ലോക്ക് ചെയ്ത ചാറ്റുകൾ മറയ്ക്കപ്പെടും",
