    "sfContactSupportDesc": "ഇവിടെ ലിസ്റ്റ് ചെയ്യാത്ത പ്രശ്നങ്ങൾക്ക് സഹായം ആവശ്യമുണ്ടോ?",
    "sfContactSupportLink": "ഞങ്ങളെ ബന്ധപ്പെടൂ →",
