    "sfPrivacyTitle": "ಗೌಪ್ಯತೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ನಿರ್ಮಿಸಲಾಗಿದೆ",
    "sfPrivacyCard1Title": "🔐 ಎನ್ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ ಸಂದೇಶಗಳು",
    "sfPrivacyCard1Desc": "ವೈಯಕ್ತಿಕ ಚಾಟ್‌ಗಳು ಎಂಡ್-ತು-ಎಂಡ್ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿವೆ. ಯಾರೂ — ಕೊನೆಗೆ ನಾವು ಸಹ — ನಿಮ್ಮ ಸಂದೇಶಗಳನ್ನು ಓದಲು ಸಾಧ್ಯವಿಲ್ಲ.",
