    "sfPrivacyCard3Title": "🗑️ ನಿಯಂತ್ರಣ ನಿಮ್ಮ ಕೈಯಲ್ಲಿದೆ",
    "sfPrivacyCard3Desc": "ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಿಂದ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಸಂದೇಶಗಳನ್ನು ಅಳಿಸಿ, ಚಾಟ್ ಇತಿಹಾಸವನ್ನು ಕ್ಲಿಯರ್ ಮಾಡಿ ಅಥವಾ ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಅಳಿಸಿ.",
    "sfHelpTitle": "ಸುರಕ್ಷತಾ ಸಹಾಯ ಬೇಕೇ?",
