    "sfHeroPill2": "🚫 ਦੁਰਵਿਹਾਰ ਲਈ ਜ਼ੀਰੋ ਸਹਿਣਸ਼ੀਲਤਾ",
    "sfHeroPill3": "⚡ 48 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਰਿਪੋਰਟ ਦੀ ਸਮੀਖਿਆ",
    "sfQuickActionsTitle": "ਤੁਰੰਤ ਸੁਰੱਖਿਆ ਉਪਾਅ",
    "sfQuickActionsSubtitle": "ਤੁਹਾਨੂੰ ਜੋ ਕੁਝ ਵੀ ਚਾਹੀਦਾ ਹੈ ਉਹ ਸਿੱਧਾ ਐਪ ਵਿੱਚ ਹੀ ਉਪਲਬਧ ਕਰਵਾਇਆ ਗਿਆ ਹੈ",
