    "sfRulesWarning": "⚠️ ਉਲੰਘਣਾ ਦੇ ਨਤੀਜੇ ਵਜੋਂ ਗੰਭੀਰਤਾ ਦੇ ਆਧਾਰ 'ਤੇ ਕਮਰਿਆਂ ਤੋਂ ਤੁਰੰਤ ਕੱਢਣਾ, ਅਸਥਾਈ ਮੁਅੱਤਲੀ ਜਾਂ ਸਥਾਈ ਪਾਬੰਦੀ ਲੱਗ ਸਕਦੀ ਹੈ।",
