    "sfPrivacyCard1Desc": "ਨਿੱਜੀ ਚੈਟ ਐਂਡ-ਟੂ-ਐਂਡ ਐਨਕ੍ਰਿਪਟਡ ਹਨ। ਕੋਈ ਵੀ — ਇੱਥੋਂ ਤੱਕ ਕਿ ਅਸੀਂ ਵੀ — ਤੁਹਾਡੇ ਸੰਦੇਸ਼ਾਂ ਨੂੰ ਨਹੀਂ ਪੜ੍ਹ ਸਕਦੇ।",
    "sfPrivacyCard2Title": "🚫 ਡੇਟਾ ਦੀ ਕੋਈ ਵਿਕਰੀ ਨਹੀਂ",
    "sfPrivacyCard2Desc": "ਅਸੀਂ ਤੁਹਾਡਾ ਡੇਟਾ ਕਦੇ ਨਹੀਂ ਵੇਚਦੇ ਹਾਂ ਅਤੇ ਨਾ ਹੀ ਵਿਗਿਆਪਨਕਰਤਾਵਾਂ ਨਾਲ ਤੁਹਾਡੀ ਗਤੀਵਿਧੀ ਸਾਂਝੀ ਕਰਦੇ ਹਾਂ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਤੁਹਾਡੀ ਹੀ ਰਹਿੰਦੀ ਹੈ।",
    "sfPrivacyCard3Title": "🗑️ ਕੰਟਰੋਲ ਤੁਹਾਡੇ ਹੱਥ ਵਿੱਚ ਹੈ",
    "sfPrivacyCard3Desc": "ਸੈਟਿੰਗਾਂ ਤੋਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਸੁਨੇਹਿਆਂ ਨੂੰ ਹਟਾਓ, ਚੈਟ ਇਤਿਹਾਸ ਸਾਫ਼ ਕਰੋ, ਜਾਂ ਆਪਣਾ ਖਾਤਾ ਪੂਰੀ ਤਰ੍ਹਾਂ ਹਟਾ ਦਿਓ।",
    "sfHelpTitle": "ਸੁਰੱਖਿਆ ਸਹਾਇਤਾ ਚਾਹੀਦੀ ਹੈ?",
    "sfHelpDesc": "ਜੇਕਰ ਤੁਸੀਂ ਪਰੇਸ਼ਾਨੀ ਦਾ ਸਾਹਮਣਾ ਕਰ ਰਹੇ ਹੋ ਜਾਂ ਅਸੁਰੱਖਿਅਤ ਮਹਿਸੂਸ ਕਰ ਰਹੇ ਹੋ, ਤਾਂ ਅਸੀਂ ਮਦਦ ਲਈ ਇੱਥੇ ਹਾਂ। ਸਾਰੀਆਂ ਰਿਪੋਰਟਾਂ ਦੀ ਨਿੱਜੀ ਤੌਰ 'ਤੇ ਸਮੀਖਿਆ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।",
