const searchTargets = {
  en: '      "rbTypeOther": "Other Bug",',
  es: '      "rbTypeOther": "Otro error",',
  fr: '      "rbTypeOther": "Autre bug",',
  de: '      "rbTypeOther": "Anderer Fehler",',
  ja: '      "rbTypeOther": "その他のバグ",',
  ko: '      "rbTypeOther": "기타 버그",',
  zh: '      "rbTypeOther": "其他未知缺陷",',
  hi: '      "rbTypeOther": "अन्य बग",',
  pt: '      "rbTypeOther": "Outro Bug",',
  ar: '      "rbTypeOther": "مشكلة أخرى",',
  ru: '      "rbTypeOther": "Другая ошибка",',
  it: '      "rbTypeOther": "Altro Bug",',
  te: '      "rbTypeOther": "ఇతర బగ్",',
  ta: '      "rbTypeOther": "இதர பிழை",',
  bn: '      "rbTypeOther": "অন্যান্য বাগ",',
  mr: '      "rbTypeOther": "इतर बग",',
  gu: '      "rbTypeOther": "અન્ય બગ",',
  ml: '      "rbTypeOther": "മറ്റ് ബഗ്",',
  kn: '      "rbTypeOther": "ಇತರ ಬಗ್",',
  pa: '      "rbTypeOther": "ਹੋਰ ਬਗ",'
};

let replaceCount = 0;
for (const [lang, searchStr] of Object.entries(searchTargets)) {
  const transObj = translations[lang];
  if (!transObj) {
    console.error(`Missing translations for ${lang}`);
    continue;
  }
  
  // Format the translation entries to insert
  const linesToInsert = Object.entries(transObj).map(([k, v]) => {
    const escapedVal = v.replace(/"/g, '\\"');
    return `      "${k}": "${escapedVal}",`;
  }).join('\n');
  
  // To avoid issues with commas, let's keep searchStr and append the lines after it
  const replacementStr = `${searchStr}\n${linesToInsert}`;
  
  const occurrences = content.split(searchStr).length - 1;
  if (occurrences === 0) {
    // If the target is the last one under the block and doesn't have a trailing comma, 
    // it might not match exact searchStr if there's no comma. Let's try matching without trailing comma as a fallback.
    const fallbackStr = searchStr.replace(/,$/, '');
    const fallbackOccurrences = content.split(fallbackStr).length - 1;
    if (fallbackOccurrences === 1) {
      // Re-replace searchStr with fallbackStr
      const fallbackReplacementStr = `${fallbackStr},\n${linesToInsert}`;
      content = content.replace(fallbackStr, fallbackReplacementStr);
      replaceCount++;
    } else {
      console.error(`Could not find search string for ${lang} even with fallback: ${searchStr}`);
    }
  } else if (occurrences > 1) {
    console.error(`Found multiple occurrences of search string for ${lang}: ${searchStr}`);
  } else {
    content = content.replace(searchStr, replacementStr);
    replaceCount++;
  }
}

if (replaceCount === Object.keys(translations).length) {
  fs.writeFileSync(filePath, content, 'utf8');
  console.log(`Successfully inserted all safety translations for ${replaceCount} languages!`);
} else {
  console.error(`Only successfully replaced ${replaceCount} out of ${Object.keys(translations).length} languages. File was NOT saved.`);
  process.exit(1);
}
